import numeral from "numeral";

numeral.register("locale", "id", {
  delimiters: {
    thousands: ".",
    decimal: ",",
  },
  abbreviations: {
    thousand: "rb",
    milion: "jt",
    billion: "m",
    trillion: "t",
  },
  currency: {
    symbol: "Rp",
  },
});

numeral.locale("id");

export const currency = (number) => {
  return numeral(number).format("$0,0");
};

export const decurrency = (number) => {
  return numeral.defaultFormat(number);
};
